import{_ as e,o as a,c as t,Q as o}from"./chunks/framework.b67c47e6.js";const s="/assets/dashboard.3903d35c.svg",g=JSON.parse('{"title":"Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"guide/management/dashboard/index.md","filePath":"guide/management/dashboard/index.md","lastUpdated":1790346505000}'),r={name:"guide/management/dashboard/index.md"},i=o('<h1 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h1><p>The Dashboard is a management area that gathers production indicators in one place. It is visible in company-wide mode and reserved for managers and admins.</p><div class="info custom-block"><p class="custom-block-title">Early preview</p><p>The Dashboard is in early preview. New charts and indicators will be added over time.</p></div><h2 id="how-to-open-it" tabindex="-1">How to open it <a class="header-anchor" href="#how-to-open-it" aria-label="Permalink to &quot;How to open it&quot;">​</a></h2><p>In the left menu, switch to company-wide mode and click <strong>Dashboard</strong> at the top of the list.</p><h2 id="choosing-the-charts" tabindex="-1">Choosing the charts <a class="header-anchor" href="#choosing-the-charts" aria-label="Permalink to &quot;Choosing the charts&quot;">​</a></h2><p>The cog button at the top right opens <strong>Dashboard settings</strong>, a list of every chart grouped by theme (Events, Throughput, Pipeline, Quality, Projects, Planning). Untick a chart to hide it, or untick a group to hide all its charts. The choice is remembered on this device.</p><p><img src="'+s+'" alt="The Dashboard"></p><ol><li><strong>Dashboard settings</strong>: pick the charts you want to see.</li><li>The period of the chart.</li><li>What your factory could start building today.</li></ol><h2 id="charts" tabindex="-1">Charts <a class="header-anchor" href="#charts" aria-label="Permalink to &quot;Charts&quot;">​</a></h2><h3 id="today-s-activity" tabindex="-1">Today&#39;s activity <a class="header-anchor" href="#today-s-activity" aria-label="Permalink to &quot;Today&#39;s activity&quot;">​</a></h3><p>A timeline of today&#39;s events since midnight, with one lane per production line and a <strong>Now</strong> marker. It shows panels and modules marked ready, stations finished, and issues opened or resolved. The counter next to the title gives the number of events, and the refresh button reloads them.</p><h3 id="assemblies-marked-ready" tabindex="-1">Assemblies marked ready <a class="header-anchor" href="#assemblies-marked-ready" aria-label="Permalink to &quot;Assemblies marked ready&quot;">​</a></h3><p>A chart that shows how many panels each production line marked as ready, stacked by line.</p><ul><li>The selector at the top right picks the period: <strong>Last 14 days</strong> (one mark per day), <strong>Last 12 weeks</strong> (the default, one mark per ISO week, Monday-based), or a whole year (this year and the two before).</li><li>Lines with no ready events in the period are not shown.</li></ul><p>Use this chart to compare throughput between lines, spot drops or peaks, and check whether weekly production is keeping a steady pace.</p><h3 id="active-backlog" tabindex="-1">Active backlog <a class="header-anchor" href="#active-backlog" aria-label="Permalink to &quot;Active backlog&quot;">​</a></h3><p>Assemblies still to produce, per production line, split by status: <em>Waiting</em>, <em>Working</em> and <em>Locked</em>. Panels already ready are not counted.</p><h3 id="ready-to-build" tabindex="-1">Ready to build <a class="header-anchor" href="#ready-to-build" aria-label="Permalink to &quot;Ready to build&quot;">​</a></h3><p>Unbuilt panels per production line, split by whether their material is there: <em>Kitted parts</em>, <em>Partly cut</em>, <em>Not cut yet</em> and <em>No parts recorded</em>. The large number at the top says how many can be built now, out of all still to build. This chart only appears when the company tracks kitted parts (see <a href="/guide/management/#interface-settings">Company settings</a>).</p><h3 id="pending-delivery" tabindex="-1">Pending delivery <a class="header-anchor" href="#pending-delivery" aria-label="Permalink to &quot;Pending delivery&quot;">​</a></h3><p>Produced assemblies that are not mounted yet, per production line, split by delivery status: <em>Unknown</em>, <em>In rack</em> and <em>Delivered</em>.</p><h3 id="issues-opened-vs-resolved" tabindex="-1">Issues opened vs resolved <a class="header-anchor" href="#issues-opened-vs-resolved" aria-label="Permalink to &quot;Issues opened vs resolved&quot;">​</a></h3><p>Issues opened and issues resolved per week, over the last 12 weeks.</p><h3 id="station-throughput" tabindex="-1">Station throughput <a class="header-anchor" href="#station-throughput" aria-label="Permalink to &quot;Station throughput&quot;">​</a></h3><p>Checklist items completed per station, one bar per week, over the last 4 weeks.</p><h3 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h3><p>Active projects against archived ones, with the total.</p><h3 id="projects-by-client" tabindex="-1">Projects by client <a class="header-anchor" href="#projects-by-client" aria-label="Permalink to &quot;Projects by client&quot;">​</a></h3><p>How the current projects are spread over clients. Clients beyond the eight largest are grouped under <em>Other</em>.</p><h3 id="design-types" tabindex="-1">Design types <a class="header-anchor" href="#design-types" aria-label="Permalink to &quot;Design types&quot;">​</a></h3><p>How many assembly and module designs there are of each type.</p><h3 id="on-time-production-and-forecast-vs-progress" tabindex="-1">On-time production and Forecast vs progress <a class="header-anchor" href="#on-time-production-and-forecast-vs-progress" aria-label="Permalink to &quot;On-time production and Forecast vs progress&quot;">​</a></h3><p>These two charts appear only when the company works by dates (<em>Production list based on dates</em> in Company settings).</p><ul><li><strong>On-time production</strong>: per week over the last 12 weeks, the share of panels marked ready on or before their scheduled production date, against a 100% target line. Panels with no scheduled date are left out.</li><li><strong>Forecast vs progress</strong>: for this week and the three after it, the panels scheduled that week, split into <em>Done</em>, <em>In progress</em> and <em>Pending</em>.</li></ul>',35),n=[i];function d(h,l,c,p,m,u){return a(),t("div",null,n)}const y=e(r,[["render",d]]);export{g as __pageData,y as default};
